import CloudKit

/// A value type that Records stores as a `CKRecord`.
///
/// Adopt it with the `@Record` macro rather than by hand. The `id` becomes the record name,
/// so it is never written as a field.
public protocol Record: Identifiable where ID == UUID {
    /// The CloudKit record type. `@Record` sets it to the type's name, or to the name it is given.
    static var recordType: CKRecord.RecordType { get }

    /// Reads the record's `id` from the record name and every other stored property from the
    /// field of the same name. Generated by `@Record`.
    init(record: CKRecord) throws

    /// Writes every stored property except `id` into `record`, keyed by property name.
    /// Generated by `@Record`.
    func encodeFields(into record: CKRecord)

    /// The names of the fields set since the record was loaded or last saved. A record made in
    /// code starts with every field changed, and a decoded one with none. Generated by `@Record`.
    var changedFields: Set<String> { get }

    /// Writes only the fields in `changedFields` into `record`. Generated by `@Record`.
    func encodeChangedFields(into record: CKRecord)

    /// Marks every field as saved, so `changedFields` is empty until one is set again.
    /// Generated by `@Record`.
    mutating func markFieldsSaved()

    /// The `@Reference(from:)` properties declared with `deleteSelf: true`. This record is
    /// deleted when the record it points at through one of them is deleted. Generated by `@Record`.
    static var deleteSelfReferences: Set<String> { get }

    /// The `@Reference(from:)` property that names `owner`'s `property`, such as `user` for
    /// `User.profile`, or `nil` when no property does. Generated by `@Record`.
    static func inverse(of property: String, in owner: CKRecord.RecordType) -> Inverse?

    /// Every `@Reference` that writes links, with its current and last saved targets.
    /// `@Reference(from:)` properties write none, so they are left out. Generated by `@Record`.
    var referenceStates: [ReferenceState] { get }

    /// Sets the `@Reference` named `property` to `targets`, in order, as read from storage.
    /// When the property holds records and `depth` is at least 1, decodes the targets found in
    /// `records` with `depth - 1`, giving them their own references from `links`. Generated by
    /// `@Record`.
    mutating func loadReference(_ property: String, to targets: [ReferenceTarget], from records: [CKRecord], links: [CKRecord], depth: Int) throws

    /// Marks every `@Reference` as saved, so it reports no changes until it changes again.
    /// Generated by `@Record`.
    mutating func markReferencesSaved()
}

/// Records without tracked fields or references.
extension Record {
    public var changedFields: Set<String> { [] }
    public func encodeChangedFields(into record: CKRecord) {}
    public mutating func markFieldsSaved() {}
    public static var deleteSelfReferences: Set<String> { [] }
    public static func inverse(of property: String, in owner: CKRecord.RecordType) -> Inverse? { nil }
    public var referenceStates: [ReferenceState] { [] }
    public mutating func loadReference(_ property: String, to targets: [ReferenceTarget], from records: [CKRecord], links: [CKRecord], depth: Int) throws {}
    public mutating func markReferencesSaved() {}
}

extension Record {
    /// Whether a field or a reference changed since the record was loaded or last saved.
    ///
    /// This covers the record's own fields and links only. A record loaded inside it, such as
    /// `album.tracks[0]`, reports its own changes.
    public var hasChanges: Bool {
        !changedFields.isEmpty || referenceStates.contains(where: \.hasChanges)
    }

    /// Marks every field and reference as saved, so `hasChanges` is `false` until the record
    /// changes again. Call it after saving what `CKRecordEncoder` returned.
    public mutating func markSaved() {
        markFieldsSaved()
        markReferencesSaved()
    }
}

/// Makes a struct a `Record`, with the struct's name as its record type.
///
/// ```swift
/// @Record struct Note {
///     var id: UUID
///     var title: String
/// }
/// ```
///
/// Generic types must pass a name with `@Record("Name")`.
///
/// Every stored `var` except `id` notes when it is set, so `changedFields` and `hasChanges`
/// report what to save. Declare each such `var` on its own line, without `willSet` or `didSet`.
@attached(memberAttribute)
@attached(extension, conformances: Record, names: named(recordType), named(init(record:)), named(encodeFields), named(changedFields), named(encodeChangedFields), named(markFieldsSaved), named(referenceStates), named(loadReference), named(markReferencesSaved), named(deleteSelfReferences), named(inverse))
public macro Record() = #externalMacro(module: "RecordsMacros", type: "RecordMacro")

/// Makes a struct a `Record` with an explicit record type.
///
/// ```swift
/// @Record("Box") struct Box<Value: CKRecordValueProtocol> { ... }
/// ```
@attached(memberAttribute)
@attached(extension, conformances: Record, names: named(recordType), named(init(record:)), named(encodeFields), named(changedFields), named(encodeChangedFields), named(markFieldsSaved), named(referenceStates), named(loadReference), named(markReferencesSaved), named(deleteSelfReferences), named(inverse))
public macro Record(_ recordType: String) = #externalMacro(module: "RecordsMacros", type: "RecordMacro")

/// Marks a property that points at other `Record`s: one, as in `@Reference var author: Person?`,
/// or many, in order, as in `@Reference var tags: [Tag]`.
///
/// The property is never written as a field. Records stores each target as a separate link,
/// which `CKRecordEncoder.linksToSave(for:in:)` writes. A decoded record has `nil` or `[]` here
/// until its links are loaded. A to-one reference must be optional and a to-many reference a
/// non-optional array, in a `var` with no initial value. Either may point at its own type.
///
/// Where loading stopped, the property reads `nil` or `[]` even when it has targets. `$name`
/// holds the IDs either way, as `[UUID]` or `UUID?`: `album.$tracks`, `album.$artist`.
@attached(accessor, names: named(init), named(get), named(set))
@attached(peer, names: prefixed(_), prefixed(`$`))
public macro Reference() = #externalMacro(module: "RecordsMacros", type: "ReferenceMacro")

/// Marks a property that holds only the IDs of other `Record`s, e.g.
/// `@Reference(Person.self) var authorID: UUID?` or `@Reference(Tag.self) var tagIDs: [UUID]`.
/// Records never loads the records themselves.
///
/// Like `@Reference`, the property is stored as links, never as a field. It must be a `UUID?`
/// or `[UUID]` with no initial value.
@attached(accessor, names: named(init), named(get), named(set))
@attached(peer, names: prefixed(_))
public macro Reference<Target: Record>(_ target: Target.Type) = #externalMacro(module: "RecordsMacros", type: "ReferenceMacro")

/// Marks the read-only side of a two-way relationship, naming the owner's property.
///
/// ```swift
/// // One-to-one
/// @Reference var profile: Profile?                                      // on User
/// @Reference(from: \User.profile, deleteSelf: true) var userID: UUID?  // on Profile
///
/// // One-to-many, owned by the many side: links are written per book, unordered
/// @Reference var shelf: Shelf?                                       // on Book
/// @Reference(from: \Book.shelf) var bookIDs: [UUID]                  // on Shelf
///
/// // One-to-many, owned by the one side: ordered, and tracks are deleted with their album
/// @Reference var tracks: [Track]                                     // on Album
/// @Reference(from: \Album.tracks, deleteSelf: true) var albumID: UUID? // on Track
///
/// // Many-to-many: the note orders its tags, and each tag lists its notes
/// @Reference var tags: [Tag]                                         // on Note
/// @Reference(from: \Note.tags) var noteIDs: [UUID]                   // on Tag
/// ```
///
/// This side always holds IDs, `UUID?` or `[UUID]`. The owner holds records, because its code
/// chose them. This side is a back-pointer: anything can point at a record, so loading every
/// owner would have no limit. To show an owner's fields, fetch it by ID, or make this side the
/// owner instead.
/// The owner writes the links, and their signature includes this side, such as
/// `User.profile:Profile <-> Profile.userID:User`. This side never writes links. It is filled from
/// the owner's links when the record is decoded, and can only be set when the record is made. A
/// to-many side lists its owners in the order their links were created. With `deleteSelf: true`,
/// which needs a to-one side, the record is deleted when its owner is deleted.
@attached(accessor, names: named(init), named(get))
@attached(peer, names: prefixed(_))
public macro Reference<Owner: Record, Value>(from owner: KeyPath<Owner, Value>, deleteSelf: Bool = false) = #externalMacro(module: "RecordsMacros", type: "ReferenceMacro")

/// Backs a stored property of a `@Record` with a `Records.Field`, which notes when it is set.
/// `@Record` adds it to each stored `var` except `id`, so you don't write it yourself.
@attached(accessor, names: named(init), named(get), named(set))
@attached(peer, names: prefixed(_))
public macro RecordField() = #externalMacro(module: "RecordsMacros", type: "RecordFieldMacro")
